"""A public project helper with contextual entry points and explicit visitor control."""
import json
import shutil
import subprocess
from editorial import write_editorial_page

def add(out,origin,pages):
    root=out.parent
    for name in ('ask-wazoozie.css','ask-wazoozie.js','ask-handoff.mjs'):
        shutil.copy(root/'assets'/name,out/'assets'/name)
    catalog=json.loads(subprocess.check_output(['node','--input-type=module','-e',"import {INTENTS,BUSINESSES} from './project-config.mjs';console.log(JSON.stringify({INTENTS,BUSINESSES}));"],cwd=root,text=True))
    (out/'assets/ask-catalog.mjs').write_text('export const CATALOG='+json.dumps(catalog)+';\n')
    body='''<section class="wrap ask-hero"><div><div class="breadcrumb"><a href="/">Home</a><span>/</span>Ask Wazoozie</div><p class="eyebrow">A GOOD PROJECT STARTS WITH A GOOD QUESTION.</p><h1>A little clarity.<br><em>A better first call.</em></h1><p>Something to fix. A room to rethink. A quote you’re trying to understand. Get your thoughts together before you call.</p><div class="ask-promise"><span>No account needed</span><span>You choose who to contact</span><span>Nothing booked automatically</span></div></div><aside><img src="/assets/valley-family-kitchen.webp" width="1280" height="853" alt="Illustrative bright kitchen with an oak island" loading="eager"><div><span>FROM “WHERE DO I START?”</span><strong>To a conversation<br>worth having.</strong></div></aside></section><section class="wrap ask-workspace" aria-label="Project planning workspace"><div class="ask-form-panel"><div class="eyebrow">LET’S SORT IT OUT.</div><h2>What would help today?</h2><div class="ask-modes" aria-label="Choose your planning task"><button type="button" data-ask-mode="plan" aria-pressed="true"><span>01</span><strong>Shape my project</strong><small>Turn a rough idea into a starting point.</small></button><button type="button" data-ask-mode="prepare" aria-pressed="false"><span>02</span><strong>Get my questions ready</strong><small>Know what to ask before the first call.</small></button><button type="button" data-ask-mode="estimate" aria-pressed="false"><span>03</span><strong>Understand a quote</strong><small>Look for scope and details to clarify.</small></button></div><form id="ask-form"><label for="ask-intent">What kind of work?</label><select id="ask-intent" required><option value="">Choose your project</option></select><p class="ask-small">Not sure which trade? <a href="/help/">Start with the problem instead →</a></p><label for="ask-question" id="ask-question-label">What would you like sorted out?</label><textarea id="ask-question" rows="5" maxlength="1800" required placeholder="Describe what changed, the work you’re considering, or what you want to understand."></textarea><div class="ask-input-meta"><span id="ask-count">0 / 1,800</span><button id="ask-example" type="button">Try an example</button></div><label class="ask-consent"><input id="ask-consent" type="checkbox" required><span>I understand my question will be processed by Cloudflare to suggest planning notes. I won’t include names, addresses, contact details, account numbers or private documents.</span></label><button type="submit" class="btn primary" id="ask-submit">Help me plan this →</button><p id="ask-status" role="status" aria-live="polite">Your question stays in this page until you choose to send it for planning help.</p></form><p class="ask-small">Suggestions help you prepare. The business confirms the actual findings, scope, coverage, price and availability. For a possible gas leak, Carbon Monoxide, fire or immediate danger, leave the area and contact emergency services or your utility from a safe location.</p></div><aside class="ask-output" aria-labelledby="ask-output-title"><div id="ask-empty"><span class="ask-monogram" aria-hidden="true">W.</span><div class="eyebrow">MAKE THE FIRST CALL COUNT.</div><h2 id="ask-output-title">You don’t need<br>all the answers yet.</h2><p>Start with what you know. We’ll help you prepare the questions.</p><ol><li>Describe the project.</li><li>Review your suggested starting point.</li><li>Choose the next step yourself.</li></ol><div class="ask-fallback"><a href="/project-kit/">Use the project checklist →</a><a href="/compare/">Compare two written estimates →</a><a href="/book/">Go straight to local contacts →</a></div></div><div id="ask-result" hidden></div></aside></section><section class="wrap ask-saved"><div><div class="eyebrow">KEEP A LITTLE CLARITY FOR LATER.</div><h2>Your saved plans.</h2><p>Only plans you choose to save appear here. They stay on this browser, not in an account or a business inbox. Anyone using this browser may be able to see them.</p></div><div id="ask-saved-list"><p>No plans saved on this browser.</p></div><button id="ask-delete-all" class="btn outline" type="button" hidden>Remove saved plans</button><p id="ask-storage-status" role="status"></p><div class="ask-share"><div><h3>Know someone with a project on their mind?</h3><p>Share the helper. Your question, answers and saved plans stay private.</p></div><button id="ask-share" class="btn outline" type="button">Share this helper →</button></div></section>'''
    write_editorial_page(out,origin,pages,'/ask/','Ask Wazoozie | Plan your project & prepare better questions','Get practical project questions, preparation notes and a clear starting point before contacting a local home-service business. You choose the next step.',body)
    target=out/'ask/index.html';s=target.read_text().replace('</head>','<link rel="stylesheet" href="/assets/ask-wazoozie.css"></head>').replace('</body>','<script type="module" src="/assets/ask-wazoozie.js"></script></body>');target.write_text(s)
    for target in out.rglob('*.html'):
        if target.parent.name in ('model-lab','account','404'):continue
        s=target.read_text()
        if '<footer' not in s:continue
        if 'href="/ask/">Ask Wazoozie' not in s:s=s.replace('<a href="/privacy/">Privacy</a>','<a href="/ask/">Ask Wazoozie</a><a href="/privacy/">Privacy</a>',1)
        relative=target.relative_to(out).as_posix()
        if relative=='index.html':
            s=s.replace('<section class="wrap wz-home-desk"','<section class="wrap ask-home-entry"><div><div class="eyebrow">GOT A PROJECT ON YOUR MIND?</div><h2>Let’s make the first call easier.</h2><p>Describe the idea, sort out your questions and leave with a plan you can keep.</p><a class="btn primary" href="/ask/">Ask Wazoozie →</a></div><aside><a href="/ask/?mode=plan"><span>01 / THE IDEA</span>Help me plan this ↗</a><a href="/ask/?mode=prepare"><span>02 / THE CONVERSATION</span>What should I ask? ↗</a><a href="/ask/?mode=estimate"><span>03 / THE QUOTE</span>What needs clarifying? ↗</a></aside></section><section class="wrap wz-home-desk"',1)
        links={'project-kit/index.html':('prepare','Get your questions ready.'),'compare/index.html':('estimate','Know what to ask about a quote.'),'pricing-guide/index.html':('estimate','Put the price in context.'),'home-services/index.html':('plan','A project in mind, but not sure where to start?'),'explore/index.html':('plan','A little help before the first call.')}
        if relative in links:
            mode,title=links[relative];band='<section class="wrap ask-context-entry"><div><span class="eyebrow">ASK WAZOOZIE</span><h2>'+title+'</h2><p>Turn a general question into useful notes for your next conversation.</p></div><a class="btn primary" href="/ask/?mode='+mode+'">Help me sort this out →</a></section>';s=s.replace('</main>',band+'</main>',1)
        if relative.startswith(('services/','businesses/')):
            slug=target.parent.name;intent=next((key for key,value in catalog['INTENTS'].items() if value.get('service')==slug),None)
            if relative.startswith('businesses/'):
                intent=next((b['defaultIntent'] for b in catalog['BUSINESSES'].values() if b['slug']==slug),None)
            if intent:s=s.replace('</main>','<section class="wrap ask-context-entry"><div><span class="eyebrow">BEFORE YOU MAKE THE CALL</span><h2>Have a few questions?</h2><p>Prepare a useful conversation about your project.</p></div><a class="btn outline" href="/ask/?mode=prepare&amp;intent='+intent+'">What should I ask? →</a></section></main>',1)
        if relative!='ask/index.html':s=s.replace('</head>','<link rel="stylesheet" href="/assets/ask-wazoozie.css"></head>',1)
        if relative=='privacy/index.html':s=s.replace('</main>','<section class="wrap"><h2>Ask Wazoozie planning help</h2><p>Questions submitted through Ask Wazoozie are processed by Cloudflare to generate suggested planning notes. Do not include contact information, addresses, account numbers or private documents. Wazoozie does not save those questions or answers on its server. Daily rotating network hashes and counters limit misuse; they are removed on the next day’s activity. Cloudflare’s processing policies apply. Plans are stored on your browser only when you choose Save on this browser, and you can remove them from the helper page. No business is notified and no appointment is created by asking a question.</p></section></main>',1)
        target.write_text(s)
